yakit.EnableTable("域名、IP提取结果", ["hosts"])
yakit.Info("域名反已启动,自动过滤不符合规范的结果")
ai_zhan := "https://apistore.aizhan.com/baidurank/siteinfos/"
str_parameter :="?domains="
domain_list:=re.FindAll(targets, `[a-zA-Z0-9]+.(com|org|net)?.(com|cn|net|org|biz|info|cc|tv|top|vip)`)
outputTable = func(hosts) {
    data = make(map[string]var)
    data["hosts"] = hosts
    yakit.TableData("域名、IP提取结果", data)
}

def Domain_get(domain_list){
    //获取对应的主域名,并且构造访问的url
    HTTP_list := []
    for index,target := range domain_list{
    domain_HTTP := ai_zhan+api_key+str_parameter+target
    HTTP_list := append(HTTP_list, domain_HTTP)
    }
    return HTTP_list
}
 URL_list := Domain_get(domain_list)
//  dump(URL_list)
//构造访问函数
def get_domain(){
    domain_list:=[]
    for index,target := range URL_list{
    rsp,err :=http.Get(target)
    raw, err2 := io.ReadAll(rsp.Body)
    die(err)
    die(err2)
    pr_str:=json.loads(string(raw))
    text_pr_1 := pr_str["data"]
    text_pr_2 :=  text_pr_1["success"]
    text_pr_3 := text_pr_2[0]
    //这上面都是对爱站拿到的json格式的数据进行处理
    domain := text_pr_3["domain"]
    m_br := text_pr_3["m_br"]
    pc_br := text_pr_3["pc_br"]
    if(parseInt(m_br)>0||parseInt(pc_br)){
        str=domain+"     "+"权重合格"
        domain_list := append(domain_list, string(str))
        }

    }
    return domain_list
}   
hosts := get_domain()
for index, element := range hosts{
    outputTable(element)
}

yakit.Info("反查结束，显示的就是爱站权重大于0的")
